import {notFound} from "next/navigation";import Link from "next/link";import {news} from "@/data/content";
export default async function Page({params}:{params:Promise<{slug:string}>}){const {slug}=await params;const n=news.find(x=>x.slug===slug);if(!n)notFound();return <><section className="pagehero"><div className="wrap"><div className="kicker">Notícias · {n.date}</div><h1>{n.title}</h1><p>{n.lead}</p></div></section><article className="section"><div className="wrap article"><img className="articleImg" src={n.image} alt={n.title}/>{n.body.map((p,i)=><p className="lead" key={i}>{p}</p>)}<Link className="button" href="/noticias">← Todas as notícias</Link></div></article></>}